INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'backfill_row_count', ((SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES) = 37), (SELECT COUNT(*)::VARCHAR FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES);
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'parity_target_minus_expected', ((SELECT COUNT(*) FROM (SELECT ORG_ID, EVENT_ID, ACCOUNT_ID, PROFILE_WEEK, EVENT_TYPE, EVENT_DATE, DETECTED_DATE, CONTACT_NAME, CONTACT_PERSONA, SENIORITY, OLD_TITLE, NEW_TITLE, NEW_EMPLOYER_NAME, NEW_ACCOUNT_ID, NEW_EMPLOYER_STATUS, PAIRED_EVENT_ID, WAS_CHAMPION, WAS_PRIMARY_CONTACT, OPPORTUNITY_SCORE, RELATIONSHIP_RISK_SCORE, PERSON_ACCOUNT_ID, LIQUIDITY_EVENT_FLAG, GENERATED_AT, RECORD_ID FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES MINUS SELECT ORG_ID, EVENT_ID, ACCOUNT_ID, PROFILE_WEEK, EVENT_TYPE, EVENT_DATE, DETECTED_DATE, CONTACT_NAME, CONTACT_PERSONA, SENIORITY, OLD_TITLE, NEW_TITLE, NEW_EMPLOYER_NAME, NEW_ACCOUNT_ID, NEW_EMPLOYER_STATUS, PAIRED_EVENT_ID, WAS_CHAMPION, WAS_PRIMARY_CONTACT, OPPORTUNITY_SCORE, RELATIONSHIP_RISK_SCORE, PERSON_ACCOUNT_ID, LIQUIDITY_EVENT_FLAG, GENERATED_AT, RECORD_ID FROM L2_EXPECTED)) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'parity_expected_minus_target', ((SELECT COUNT(*) FROM (SELECT ORG_ID, EVENT_ID, ACCOUNT_ID, PROFILE_WEEK, EVENT_TYPE, EVENT_DATE, DETECTED_DATE, CONTACT_NAME, CONTACT_PERSONA, SENIORITY, OLD_TITLE, NEW_TITLE, NEW_EMPLOYER_NAME, NEW_ACCOUNT_ID, NEW_EMPLOYER_STATUS, PAIRED_EVENT_ID, WAS_CHAMPION, WAS_PRIMARY_CONTACT, OPPORTUNITY_SCORE, RELATIONSHIP_RISK_SCORE, PERSON_ACCOUNT_ID, LIQUIDITY_EVENT_FLAG, GENERATED_AT, RECORD_ID FROM L2_EXPECTED MINUS SELECT ORG_ID, EVENT_ID, ACCOUNT_ID, PROFILE_WEEK, EVENT_TYPE, EVENT_DATE, DETECTED_DATE, CONTACT_NAME, CONTACT_PERSONA, SENIORITY, OLD_TITLE, NEW_TITLE, NEW_EMPLOYER_NAME, NEW_ACCOUNT_ID, NEW_EMPLOYER_STATUS, PAIRED_EVENT_ID, WAS_CHAMPION, WAS_PRIMARY_CONTACT, OPPORTUNITY_SCORE, RELATIONSHIP_RISK_SCORE, PERSON_ACCOUNT_ID, LIQUIDITY_EVENT_FLAG, GENERATED_AT, RECORD_ID FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES)) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'record_id_sql_matches_python_form', ((SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES t JOIN L2_EXPECTED e ON e.EVENT_ID = t.EVENT_ID WHERE t.RECORD_ID <> e.RECORD_ID) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'generated_at_is_profile_week_midnight', ((SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES WHERE GENERATED_AT <> PROFILE_WEEK::TIMESTAMP_NTZ OR DAYOFWEEKISO(PROFILE_WEEK) <> 1 OR PROFILE_WEEK <> DATEADD(day, 1 - DAYOFWEEKISO(DETECTED_DATE), DETECTED_DATE)) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'detected_in_window', ((SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES WHERE DETECTED_DATE < '2024-11-04' OR DETECTED_DATE > '2026-11-02') = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'csuite_exactly_one_per_complete_rise', ((SELECT COUNT(*) FROM L2_COMPLETE_RISES r WHERE (SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES t WHERE t.ACCOUNT_ID = r.ACCOUNT_ID AND DATE_TRUNC('month', t.EVENT_DATE) = r.PROFILE_MONTH AND t.EVENT_TYPE = 'Departed' AND SENIORITY = 'C-Suite') <> 1) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'csuite_never_outside_a_rise', ((SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES t WHERE t.EVENT_TYPE = 'Departed' AND SENIORITY = 'C-Suite' AND NOT EXISTS (SELECT 1 FROM (SELECT * FROM L2_COMPLETE_RISES UNION ALL SELECT * FROM L2_INCOMPLETE_RISES) r WHERE r.ACCOUNT_ID = t.ACCOUNT_ID AND r.PROFILE_MONTH = DATE_TRUNC('month', t.EVENT_DATE))) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'csuite_at_most_one_per_account_month', ((SELECT COUNT(*) FROM (SELECT ACCOUNT_ID, DATE_TRUNC('month', EVENT_DATE) m FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES WHERE EVENT_TYPE = 'Departed' AND SENIORITY = 'C-Suite' GROUP BY 1, 2 HAVING COUNT(*) > 1)) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'pairs_present', ((SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES WHERE PAIRED_EVENT_ID IS NOT NULL) > 0), (SELECT COUNT(*)::VARCHAR FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES WHERE PAIRED_EVENT_ID IS NOT NULL);
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'pairs_cross_linked', ((SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES a JOIN DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES b ON b.EVENT_ID = a.PAIRED_EVENT_ID WHERE b.PAIRED_EVENT_ID <> a.EVENT_ID OR a.EVENT_ID = a.PAIRED_EVENT_ID OR a.EVENT_TYPE = b.EVENT_TYPE) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'pair_mirror_on_new_account', ((SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES d JOIN DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES j ON j.EVENT_ID = d.PAIRED_EVENT_ID WHERE d.EVENT_TYPE = 'Departed' AND (d.NEW_ACCOUNT_ID IS NULL OR j.ACCOUNT_ID <> d.NEW_ACCOUNT_ID OR d.NEW_ACCOUNT_ID = d.ACCOUNT_ID)) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'unmatched_pairs_only_at_window_edges', ((SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES a WHERE a.PAIRED_EVENT_ID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES b WHERE b.EVENT_ID = a.PAIRED_EVENT_ID) AND NOT ((a.EVENT_TYPE = 'Departed' AND a.DETECTED_DATE > DATEADD(day, -7, '2026-11-02')) OR (a.EVENT_TYPE = 'Joined' AND a.DETECTED_DATE < DATEADD(day, 7, '2024-11-04')))) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'no_household_or_out_of_audience_rows', ((SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES WHERE ACCOUNT_ID = '001UG0000000901AAA' OR NEW_ACCOUNT_ID = '001UG0000000901AAA' OR ACCOUNT_ID NOT IN (SELECT ACCOUNT_ID FROM L2_ANCHORS WHERE ACCOUNT_TYPE_FLAG = 'BUSINESS' AND COALESCE(CLIENT_CATEGORY, '') <> 'Household')) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'liquidity_rows_tie_to_wealth_pool', ((SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES WHERE LIQUIDITY_EVENT_FLAG) > 0 AND (SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES WHERE LIQUIDITY_EVENT_FLAG <> (PERSON_ACCOUNT_ID IS NOT NULL) OR (PERSON_ACCOUNT_ID IS NOT NULL AND PERSON_ACCOUNT_ID NOT IN (SELECT ACCOUNT_ID FROM L2_ANCHORS WHERE CLIENT_CATEGORY = 'Wealth Management'))) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'staging_dates_land_as_number', ((SELECT DATA_TYPE FROM DEMO_DB.INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = 'CUMULUS_L2_USERGEMS' AND TABLE_NAME = 'USERGEMS_JOB_CHANGES_STAGING' AND COLUMN_NAME = 'EVENT_DATE') = 'NUMBER'), (SELECT DATA_TYPE FROM DEMO_DB.INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = 'CUMULUS_L2_USERGEMS' AND TABLE_NAME = 'USERGEMS_JOB_CHANGES_STAGING' AND COLUMN_NAME = 'EVENT_DATE');
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'log_succeeded_backfill', ((SELECT COUNT(*) FROM TASK_EXECUTION_LOG WHERE TASK_NAME = 'TASK_WEEKLY_USERGEMS_JOB_CHANGES_FIXTURE' AND STATUS = 'SUCCEEDED' AND ROWS_INSERTED = 37 AND ACCOUNTS_PROCESSED = 11) = 1), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'rerun_identical', ((SELECT N FROM L2_HASH) = (SELECT COUNT(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES) AND (SELECT H FROM L2_HASH) = (SELECT HASH_AGG(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES)), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'rerun_inserted_zero', ((SELECT ROWS_INSERTED FROM TASK_EXECUTION_LOG WHERE TASK_NAME = 'TASK_WEEKLY_USERGEMS_JOB_CHANGES_FIXTURE' ORDER BY EXECUTION_TIME DESC LIMIT 1) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'contract_a_raises_on_strict_band', CONTAINS($1, 'contract (a)'), SUBSTR($1, POSITION('event contract' IN $1), 200) FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()));
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'strict_failure_logged', ((SELECT COUNT(*) FROM TASK_EXECUTION_LOG WHERE TASK_NAME = 'TASK_WEEKLY_USERGEMS_JOB_CHANGES_STRICT_FIXTURE' AND STATUS = 'FAILED') = 1), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'contract_d_raises_on_non_rise_departure', CONTAINS($1, 'contract (d)'), SUBSTR($1, POSITION('event contract' IN $1), 200) FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()));
INSERT INTO DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES SELECT * FROM L2_S0;
INSERT INTO DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES SELECT ORG_ID, UUID_STRING(), UUID_STRING(), ACCOUNT_ID, PROFILE_WEEK, EVENT_TYPE, EVENT_DATE, DETECTED_DATE, CONTACT_NAME, CONTACT_PERSONA, SENIORITY, OLD_TITLE, NEW_TITLE, NEW_EMPLOYER_NAME, NEW_ACCOUNT_ID, NEW_EMPLOYER_STATUS, NULL, WAS_CHAMPION, WAS_PRIMARY_CONTACT, OPPORTUNITY_SCORE, RELATIONSHIP_RISK_SCORE, NULL, FALSE, GENERATED_AT FROM L2_S0 WHERE EVENT_TYPE = 'Departed' AND SENIORITY = 'C-Suite' AND ACCOUNT_ID = '001UG0000000008AAA' AND DATE_TRUNC('month', EVENT_DATE) = '2025-09-01';
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'contract_d_raises_on_duplicate_departure', CONTAINS($1, 'contract (d)'), SUBSTR($1, POSITION('event contract' IN $1), 200) FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()));
INSERT INTO DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES SELECT * FROM L2_S0;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'restored_after_negative_tests', ((SELECT HASH_AGG(*) FROM DEMO_DB.CUMULUS_L2_USERGEMS.USERGEMS_JOB_CHANGES) = (SELECT H FROM L2_HASH)), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'overlap_run1_rows', ((SELECT COUNT(*) FROM L2_S1) = 1), (SELECT COUNT(*)::VARCHAR FROM L2_S1);
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'overlap_run2_rows', ((SELECT COUNT(*) FROM L2_S2) = 1), (SELECT COUNT(*)::VARCHAR FROM L2_S2);
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'overlap_ids_detected_on_shared_monday', ((SELECT COUNT(*) FROM L2_S1 a JOIN L2_S2 b ON b.EVENT_ID = a.EVENT_ID) = 1 AND (SELECT COUNT(*) FROM L2_S1 a JOIN L2_S2 b ON b.EVENT_ID = a.EVENT_ID WHERE a.DETECTED_DATE <> '2026-10-19') = 0), '1 overlapping ids';
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'overlap_rows_identical', ((SELECT COUNT(*) FROM (SELECT * FROM L2_S1 WHERE EVENT_ID IN (SELECT EVENT_ID FROM L2_S2) MINUS SELECT * FROM L2_S2)) = 0), NULL;
INSERT INTO L2_RESULTS (NAME, OK, DETAIL) SELECT 'overlap_union_equals_backfill_no_gap', ((SELECT COUNT(*) FROM ((SELECT * FROM L2_S1 UNION SELECT * FROM L2_S2) MINUS SELECT * FROM L2_S0 WHERE DETECTED_DATE BETWEEN '2026-10-12' AND '2026-10-26')) = 0 AND (SELECT COUNT(*) FROM (SELECT * FROM L2_S0 WHERE DETECTED_DATE BETWEEN '2026-10-12' AND '2026-10-26' MINUS (SELECT * FROM L2_S1 UNION SELECT * FROM L2_S2))) = 0), NULL;
